fixed_code:
def consume_events(connection, callback):
    channel = connection.channel()
    while True:
        try:
            event = channel.drain_events(timeout=1.0)
            if event:
                callback(event)
        except socket.timeout:
            continue
        except (ConnectionResetError, BrokenPipeError) as exc:
            logger.warning("Broker connection reset, reconnecting: %s", exc)
            connection = reconnect()
            channel = connection.channel()
